import re
from collections import Counter

PATTERN = re.compile(r"Failed password for (?:invalid user )?(\S+) from (\S+) port")

def top_offender(lines):
    counts = Counter()
    for line in lines:
        m = PATTERN.search(line)
        if m:
            counts[m.group(2)] += 1
    if not counts:
        return {"ip": None, "failures": 0}
    ip, failures = counts.most_common(1)[0]
    return {"ip": ip, "failures": failures}
